        representationId: source.documentId, name: metadata.name, revisionId: 'compare-snapshot', savedName: metadata.name,
        savedScene: JSON.stringify(document.scene), savedEdges: JSON.stringify(document.edges), document, canvas
      }] });
      const copy: CompareCanvasCopy = { id: randomUUID(), source, canvasName: generated?.generated.contextName ?? metadata.name, history: copiedHistory,
        ...(generated ? { generated: structuredClone(generated.generated) } : {}),
        view: { id: randomUUID(), name: view?.name ?? metadata.name, createdAt, savedAt: createdAt,
          startCheckpointId: source.checkpointId, finalCheckpointId: source.checkpointId, checkpointIds: [source.checkpointId],
          ...(view?.generation ? { generation: structuredClone(view.generation) } : {}) } };
      copies.set(key, copy); return copy;
    };
    sources.forEach(capture);
    return { projectId: index.projectId, canvases: [...copies.values()] };
  }
  async createPinned(input: unknown, captured: { projectId: string; canvases: CompareCanvasCopy[] }): Promise<ComparePageSession> {
    const request = createCompareSessionSchema.parse(input), requestHash = sha256(JSON.stringify(request));
    const copies = new Map(captured.canvases.map(copy => [JSON.stringify(copy.source), structuredClone(copy)]));
    const capture = ({ documentId, viewId, checkpointId }: CompareSource) => {
      const copy = copies.get(JSON.stringify({ documentId, ...(viewId ? { viewId } : {}), checkpointId }));
      if (!copy) throw new ApplicationError('invalid-input', 'Comparison source was not captured.');
      return copy;
    };
    const createdAt = new Date().toISOString();
    const pane = (copy: CompareCanvasCopy) => {
      const canvas = copy.history.snapshots[copy.history.headId].view as MappingCanvasState;
      // Same default as Mapping's native camera (360, 100, 1), in persisted coordinates.
      return { canvasCopyId: copy.id, camera: { transform: structuredClone(canvas?.viewport ?? { offset: { x: 170, y: 36 }, scale: 1 }) } };
    };
    const compares = request.pairs.map(pair => {
      const A = capture(pair.A), B = capture(pair.B);
      if (pair.A.diagram && pair.B.diagram) {
        const diagramPane = (copy: CompareCanvasCopy, target: NonNullable<CreateCompareSession['pairs'][number]['A']['diagram']>): CompareDiagramPaneSpec => {
          const pinned = diagramTargets(copy.history).find(item => item.diagramId === target.diagramId);
          if (!pinned) throw new ApplicationError('invalid-input', `Unknown diagram: ${target.diagramId}`);
          if (pinned.revisionId !== target.revisionId) throw new ApplicationError('conflict', 'The selected diagram revision does not match this snapshot. Refresh the views.');
          if (target.ranges?.some(range => range.endLine > copy.history.diagramRevisions[target.revisionId].diagram.content.ascii.split('\n').length))
            throw new ApplicationError('invalid-input', 'Comparison slice is outside the diagram.');
          if (target.nodeRef) {
            try { revisionScope(copy.history.diagramRevisions[target.revisionId], target.nodeRef); }
            catch { throw new ApplicationError('invalid-input', 'The selected subtree does not exist in this revision.'); }
          }
          return { kind: 'diagram', canvasCopyId: copy.id, ...target };
        };
        return { id: randomUUID(), title: pair.title ?? `${A.view.name} / ${B.view.name}`, ...(pair.explanation ? { explanation: pair.explanation } : {}), A: diagramPane(A, pair.A.diagram), B: diagramPane(B, pair.B.diagram) };
      }
      const diagrams = (copy: CompareCanvasCopy) => {
        const document = documentFromHistory(copy.history);
        return flattenGrid(resolveScene(document.scene)).filter(box => box.box.kind === 'diagram' && box.contentId)
          .sort((a, b) => a.bounds.row - b.bounds.row || a.bounds.column - b.bounds.column || a.box.id.localeCompare(b.box.id))
          .map(box => ({ id: `grid:${box.box.id}`, title: document.scene.contents[box.contentId!].content.ascii.split('\n').find(line => line.trim())?.slice(0, 200) || 'Diagram' }));
      };
      const targetsA = diagrams(A), targetsB = diagrams(B);
      // A self-comparison is the manual smoke-test tour, with explicit identical targets.
      const focusPairs = pair.focusPairs ?? (A.id === B.id ? targetsA.slice(0, 3).map(target => ({ title: target.title, A: target.id, B: target.id })) : []);
      const camera = (copy: CompareCanvasCopy, target: string, title: string, targets: typeof targetsA) => {
        if (!targets.some(item => item.id === target)) throw new ApplicationError('invalid-input', `Unknown diagram focus: ${target}`);
        const cameras = copy.view.cameraViews ??= [];
        const existing = cameras.find(camera => camera.focus.type === 'DiagramFocused' && camera.focus.diagramId === target);
        if (existing) return existing.id;
        const id = randomUUID(); cameras.push({ id, title, focus: { type: 'DiagramFocused', diagramId: target } });
        copy.view.defaultCameraViewId ??= id;
        return id;
      };
      const points = focusPairs.map(point => ({ id: randomUUID(), title: point.title,
        A: camera(A, point.A, point.title, targetsA), B: camera(B, point.B, point.title, targetsB) }));
      return { id: randomUUID(), title: A.id === B.id ? A.view.name : `${A.view.name} / ${B.view.name}`, A: pane(A), B: pane(B), ...(points.length ? { points } : {}) };
    });
    return this.store.create({ schemaVersion: 1, id: request.requestId, projectId: captured.projectId, title: request.title,
      createdAt, requestHash, canvases: [...copies.values()], compares });
  }
}
"},{"path":"application/mapping/compare/comparisonGenerationService.ts","text":"import { comparisonManifest, comparisonReportPromptVersion, promptExperimentPrompt, resolveComparisonReport } from '../../../domain/mapping/compare/comparisonReport';
import { generatedWorkflow } from '../../../domain/core/diagrams/generatedCanvas';
import { ApplicationError } from '../../core/errors';
import { sha256 } from '../../../domain/core/sha256';
import { comparisonPrompt, generateComparisonSchema, generatedComparisonsSchema, summarizeComparisonRun, type ComparisonRun, type ComparisonInputDiagram, type GenerateComparison } from '../../../domain/mapping/compare/comparisonGeneration';
import { diagramTargets, type CompareSessionService } from './compareSessionService';

export interface ComparisonRunStore {
  list(): Promise<ComparisonRun[]>; read(id: string): Promise<ComparisonRun | null>; save(run: ComparisonRun): Promise<void>; delete(id: string): Promise<void>;
}
export interface ComparisonRuntime {
  generate(input: { diagrams: ComparisonInputDiagram[]; model: string; effort: string; signal: AbortSignal; evaluationPrompt?: string; experiment?: GenerateComparison['experiment']; canvases?: ComparisonRun['canvases'] }): Promise<{ output: unknown; usage?: Record<string, number> }>;
}
export class ComparisonGenerationService {
  private deleted = new Set<string>();
  private saves = new Map<string, Promise<void>>();
  private ready: Promise<void>;
  private starts = new Map<string, Promise<ComparisonRun>>();
  private running = new Map<string, AbortController>();
  constructor(private comparisons: CompareSessionService, private store: ComparisonRunStore, private runtime: ComparisonRuntime) {
    comparisons.onDelete = id => this.deleteRecord(id);
    this.ready = store.list().then(async runs => {
      for (const run of runs) if (run.status === 'queued' || run.status === 'generating') {
        // A crash after publishing the session must not lose the successful result.
        const saved = await comparisons.read(run.id).catch(() => undefined);
        if (run.report) { await store.save({ ...run, status: 'finished', completedAt: run.completedAt ?? new Date().toISOString() }); continue; }
        await store.save({ ...run, status: saved ? 'finished' : 'failed', completedAt: new Date().toISOString(),
          ...(saved ? { sessionId: saved.id } : { error: 'Server restarted during comparison. Start a new run to retry.' }) });
      }
    });
    void this.ready.catch(() => {});
  }
  async list(documentId?: string) {
    await this.ready;
    return (await this.store.list()).filter(run => !documentId || run.request.sources.some(s => s.documentId === documentId))
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt)).map(summarizeComparisonRun);
  }
  async read(id: string) {
    await this.ready;
    const run = await this.store.read(id);
    if (!run) throw new ApplicationError('invalid-input', 'Comparison run not found.');
    return run;
  }
  async start(raw: unknown) {
    await this.ready;
    const input = generateComparisonSchema.parse(raw), hash = sha256(JSON.stringify(input));
    if (this.deleted.has(input.requestId)) throw new ApplicationError('conflict', 'This comparison was deleted. Use a new request ID.');
    let pending = this.starts.get(input.requestId);
    if (!pending) {
      pending = (async () => {
        const existing = await this.store.read(input.requestId);
        return existing ?? this.prepare(input, hash);
      })();
      this.starts.set(input.requestId, pending);
    }
    try {
      const run = await pending;
      if (run.requestHash !== hash) throw new ApplicationError('conflict', 'Request ID already used for another comparison run.');
      return summarizeComparisonRun(run);
    } finally { if (this.starts.get(input.requestId) === pending) this.starts.delete(input.requestId); }
  }
  private async prepare(input: GenerateComparison, requestHash: string) {
    const captured = await this.comparisons.capture(input.sources);
    if (captured.canvases.some(copy => copy.view.generation && copy.view.generation.status !== 'finished'))
      throw new ApplicationError('invalid-input', 'Wait for selected alternatives to finish generation.');
    const diagrams = captured.canvases.flatMap(copy => diagramTargets(copy.history).map(target => ({
      id: '', name: `${copy.view.name} — ${target.name}`, canvasCopyId: copy.id, diagramId: target.diagramId, revisionId: target.revisionId,
      ascii: copy.history.diagramRevisions[target.revisionId].diagram.content.ascii
    }))).map((diagram, i) => ({ ...diagram, id: `D${i + 1}` }));
    if (captured.canvases.some(copy => !diagrams.some(diagram => diagram.canvasCopyId === copy.id)))
      throw new ApplicationError('invalid-input', 'Every selected view needs a diagram.');
    if (diagrams.length > 80 || diagrams.reduce((sum, d) => sum + d.ascii.length, 0) > 2_000_000)
      throw new ApplicationError('invalid-input', 'Select fewer or smaller diagrams.');
    const run: ComparisonRun = { id: input.requestId, request: input, requestHash, ...captured, diagrams,
      evaluationPromptVersion: input.experiment ? comparisonReportPromptVersion : 1,
      evaluationPrompt: input.experiment ? promptExperimentPrompt(input.experiment, comparisonManifest(captured.canvases, input.experiment), diagrams, captured.canvases) : comparisonPrompt(diagrams),
      status: 'queued', createdAt: new Date().toISOString() };
    await this.store.save(run);
    const abort = new AbortController(); this.running.set(run.id, abort);
    void this.execute(structuredClone(run), abort.signal).finally(() => this.running.delete(run.id)).catch(() => {});
    return run;
  }
  private persist(run: ComparisonRun) {
    const copy = structuredClone(run);
    const pending = (this.saves.get(run.id) ?? Promise.resolve()).then(async () => { if (!this.deleted.has(run.id)) await this.store.save(copy); });
    this.saves.set(run.id, pending.catch(() => {})); return pending;
  }
  async deleteContextOutputs(agentContextId: string, workflow: string) {
    await this.ready;
    for (const run of await this.store.list()) if (run.canvases.length && run.canvases.every(copy =>
      copy.generated?.agentContextId === agentContextId && generatedWorkflow(copy.generated) === workflow)) await this.delete(run.id);
  }
  private async execute(run: ComparisonRun, signal: AbortSignal) {
    try {
      run.status = 'generating'; await this.persist(run);
      const result = await this.runtime.generate({ diagrams: run.diagrams, model: run.request.model, effort: run.request.effort, signal, evaluationPrompt: run.evaluationPrompt, experiment: run.request.experiment, canvases: run.canvases });
      signal.throwIfAborted();
      if (run.request.experiment) {
        run.report = resolveComparisonReport(result.output, run.canvases, run.request.experiment, run.diagrams);
        run.status = 'finished'; run.usage = result.usage; run.completedAt = new Date().toISOString();
        await this.persist(run); return;
      }
      const output = generatedComparisonsSchema.parse(result.output), used = new Set<string>();
      const side = (target: typeof output.comparisons[number]['A']) => {
        const diagram = run.diagrams.find(diagram => diagram.id === target.diagram);
        if (!diagram) throw Error(`Unknown comparison diagram: ${target.diagram}`);
        const copy = run.canvases.find(copy => copy.id === diagram.canvasCopyId)!;
        used.add(copy.id);
        if (target.ranges.some(range => range.endLine > diagram.ascii.split('\n').length)) throw Error(`Slice exceeds ${diagram.id}`);
        return { ...copy.source, diagram: { diagramId: diagram.diagramId, revisionId: diagram.revisionId, ranges: target.ranges } };
      };
      const pairs = output.comparisons.map(comparison => {
        const A = side(comparison.A), B = side(comparison.B);
        if (A.documentId === B.documentId && A.viewId === B.viewId) throw Error('Comparison must use two distinct alternatives.');
        return { title: comparison.title, explanation: comparison.explanation, A, B };
      });
      if (used.size !== run.canvases.length) throw Error('The comparison omitted a selected alternative.');
      const session = await this.comparisons.createPinned({ requestId: run.id, title: run.request.title, pairs }, run);
      if (this.deleted.has(run.id)) { await this.comparisons.delete(session.id); return; }
      run.status = 'finished'; run.sessionId = session.id; run.usage = result.usage;
    } catch (error) { run.status = 'failed'; run.error = error instanceof Error ? error.message : String(error); }
    run.completedAt = new Date().toISOString(); await this.persist(run);
  }
  /** Removes a comparison run and the session it published, if any. */
  async delete(id: string) {
    await this.deleteRecord(id);
    await this.comparisons.delete(id).catch(() => {});
  }
  private async deleteRecord(id: string) {
    await this.ready;
    this.deleted.add(id); this.running.get(id)?.abort();
    await this.saves.get(id);
    await this.store.delete(id);
  }
  dispose() { for (const abort of this.running.values()) abort.abort(); }
}
