654:   private async generateValidated<T>({ body, values, templateBase, ...input }: Generation, validate: (output: unknown) => T) {
655:     const workflow = evalWorkflows[input.workflow];
656:     const prompt = composePrompt(workflow, input.stage, body, values, templateBase);
657:     let files = input.files;
658:     const usage: Record<string, number> = {};
659:     for (let attempt = 0; ; attempt++) {
660:       input.signal.throwIfAborted();
661:       const response = await this.runtime.generate({ ...input, prompt, files }); input.signal.throwIfAborted();
662:       for (const [key, value] of Object.entries(response.usage ?? {})) usage[key] = (usage[key] ?? 0) + value;
663:       try { return { result: validate(response.output), usage, execution: response.execution }; }
664:       catch (error) {
665:         if (attempt >= 2) throw error;
666:         files = { ...input.files, 'previous-output.json': response.output, 'validation-error.json': { error: String(error) } };
667:       }
668:     }
669:   }
670:   /** Idempotent promotion of pre-Evals generated views. Original checkpoints remain available. */
671:   async migrate() {
672:     if (this.migration) return this.migration;
673:     this.migration = this.migrateLegacy();
674:     try { return await this.migration; } finally { this.migration = undefined; }
675:   }
676:   private async migrateLegacy() {
677:     const project = await this.projects.loadProject(); if (!project) return { migrated: 0 };
678:     const catalog = await (this.projects.projectCatalogs.loadCurrentRepresentationCatalog?.(project.id, []) ?? this.projects.projectCatalogs.loadRepresentationCatalog(project.id));
679:     // Archived keys also count: promotion must not resurrect a deleted output.
680:     const existing = new Set(Object.values(catalog.representations).map(c => c.generated?.key));
681:     for (const canvas of Object.values(catalog.representations)) if (canvas.status === 'settled' && canvas.generated?.generation && canvas.generated.generation.status !== 'finished')
682:       await this.projects.projectCatalogs.archiveRepresentation(project.id, canvas.id, { includeHistory: false });
683:     const headers = await this.workspace.loadViewHeaders?.();
684:     if (headers) {
685:       const views = headers.filter(header => header.type !== 'generated').flatMap(header =>
686:         Object.values(header.canvasViews?.saved ?? {}).filter(view => !view.archivedAt).map(view => ({ documentId: header.documentId, view })));
687:       const runIds = [...new Set(views.flatMap(({ view }) => view.generation ? [view.generation.runId] : []))];
688:       const recorded = new Set((await Promise.all(runIds.map(async id => await this.store.read(legacyEvalRunId(id)) ? id : undefined))).filter(Boolean));
689:       const pending = views.some(({ documentId, view }) => view.generation
690:         ? !recorded.has(view.generation.runId) && !['queued', 'generating'].includes(view.generation.status)
