692:       if (!pending) return { migrated: 0 };
693:     }
694:     const { records } = await this.workspace.loadRecords('current'), index = records.workspace as WorkspaceIndex | undefined;
695:     if (!index) return { migrated: 0 };
696:     let migrated = 0;
697:     for (const documentId of index.documentIds) {
698:       const metadata = records[documentPrefix(documentId) + 'metadata'] as MappingDocumentSnapshot;
699:       if (metadata.type === 'generated') continue;
700:       const history = recordHistory(records, documentId);
701:       const generatedViews = Object.values(history.canvasViews?.saved ?? {}).filter(view => view.generation && !view.archivedAt);
702:       for (const runId of new Set(generatedViews.map(view => view.generation!.runId))) {
703:         // Chat lifecycle records win; migration must never overwrite their pinned source or prompt text.
704:         if (await this.store.read(legacyEvalRunId(runId))) continue;
705:         // The chat observer owns active generations, including the interval before its first save.
706:         if (generatedViews.some(view => view.generation!.runId === runId && ['queued', 'generating'].includes(view.generation!.status))) continue;
707:         const children = generatedViews.filter(view => view.generation!.runId === runId).map(view => ({
708:           id: view.generation!.chatId, title: view.name,
709:           generation: { metadata: view.generation!, viewId: view.id, parentViewId: view.parentViewId ?? '', source: { documentId, workspaceInstanceId: 'migration' },
710:             ...(view.finalCheckpointId ? { history: { ...structuredClone(history), headId: view.finalCheckpointId, baselineId: view.forkCheckpointId ?? view.startCheckpointId } } : {}) }
711:         } as import('../../../domain/mapping/agent-chat/agentChat').ChatSession));
712:         await this.recordLegacy(children, undefined, true);
713:         migrated += children.filter(child => child.generation!.metadata.status === 'finished' && child.generation!.history && !existing.has(`legacy:${documentId}:${child.generation!.viewId}`)).length;
714:       }
715:       for (const view of Object.values(history.canvasViews?.saved ?? {})) {
716:         const key = `legacy:${documentId}:${view.id}`;
717:         if (view.generation) continue;
718:         if (!view.alternativeGroupId || view.archivedAt || !view.finalCheckpointId || existing.has(key)) continue;
719:         const group = view.alternativeGroupId;
720:         const hex = sha256(`${documentId}:${group}`).slice(0, 32);
721:         const requestId = `${hex.slice(0,8)}-${hex.slice(8,12)}-4${hex.slice(13,16)}-8${hex.slice(17,20)}-${hex.slice(20)}`;
722:         const contextName = `Migrated generation · ${metadata.name}`.slice(0,120);
723:         const { agentContextId } = await this.contexts.create({ requestId, name: contextName,
724:           context: JSON.stringify({ sourceDocumentId: documentId, generationRunId: group }) });
725:         const copy = copyCompareHistory(history, view.finalCheckpointId), document = documentFromHistory(copy);
726:         await this.projects.projectCatalogs.saveMappingDiagram(index.projectId, { name: view.name.slice(0, 120), type: 'generated', history: copy, scene: document.scene, edges: document.edges,
727:           repositoryId: metadata.repositoryId ?? (project?.repositories?.length === 1 ? project.repositories[0].id : undefined),
728:           generated: { key, agentContextId, contextName, stage: 'legacy', source: { documentId, viewId: view.id, checkpointId: view.finalCheckpointId }, generation: view.generation } });
729:         migrated++;
730:       }
731:     }
732:     return { migrated };
733:   }
734:   /** Archives a generated canvas, like deleting it in Mapping. */
735:   async deleteCanvas(id: string) {
736:     if (!(await this.canvases.list()).some(canvas => canvas.id === id)) throw new ApplicationError('invalid-input', 'Generated canvas not found.');
737:     const project = await this.projects.loadProject();
738:     if (!project) throw new ApplicationError('invalid-input', 'Open a project first.');
739:     await this.projects.projectCatalogs.archiveRepresentation(project.id, id, { includeHistory: false });
740:   }
741:   /** Cancels the run if needed, archives its canvases and removes the record, along with its reruns. */
742:   async deleteRun(id: string) {
743:     await this.read(id);
744:     for (const rerun of await this.store.list()) if (!rerun.deletedAt && rerun.parentRunId === id) await this.deleteRun(rerun.id);
745:     await this.deleteSingleRun(id);
746:   }
747:   /** Deletes exactly the selected runs; reruns in other navigation groups are kept. */
748:   async deleteRuns(ids: string[]) {
749:     const selected = new Set(ids);
750:     for (const run of await this.list()) if (selected.has(run.id)) await this.deleteSingleRun(run.id);
751:   }
752:   private async deleteSingleRun(id: string) {
753:     const run = await this.read(id);
754:     this.deleted.add(id);
755:     if (run.compatibility && this.cancelLegacy) await Promise.all(run.compatibility.candidates.map(c => this.cancelLegacy!(c.chatId)));
756:     this.running.get(id)?.abort();
757:     await this.legacyGenerations.drain();
758:     await this.saves.get(id);
759:     const live = new Set((await this.canvases.list()).map(canvas => canvas.id));
760:     for (const cell of run.cells) if (cell.canvasId && live.has(cell.canvasId)) await this.deleteCanvas(cell.canvasId);
761:     await this.store.save({ ...run, deletedAt: new Date().toISOString() });
762:     if (run.legacy) await this.legacy?.delete(id).catch(() => {});
763:   }
764:   /** Removes everything one workflow generated from an AgentContext. The context itself is kept. */
765:   async deleteContextOutputs(agentContextId: string, workflow: EvalWorkflowId) {
766:     await this.deleteContextComparisons?.(agentContextId, workflow);
767:     await this.deleteRuns((await this.list()).filter(run => run.agentContextId === agentContextId && run.workflow === workflow).map(run => run.id));
768:     for (const canvas of await this.canvases.list())
769:       if (canvas.generated?.agentContextId === agentContextId && generatedWorkflow(canvas.generated) === workflow) await this.deleteCanvas(canvas.id);
770:     for (const session of await this.comparisons.list())
771:       if ((await this.comparisons.read(session.id)).canvases.every(copy => copy.generated?.agentContextId === agentContextId && generatedWorkflow(copy.generated) === workflow)) await this.comparisons.delete(session.id);
772:   }
773:   dispose() { for (const abort of this.running.values()) abort.abort(); this.runtime.dispose?.(); }
774: }

